import{_ as a,o as l,c as i,a6 as e}from"./chunks/framework.UJjEHsnG.js";const b=JSON.parse('{"title":"硬件","description":"","frontmatter":{},"headers":[],"relativePath":"doc/hardware.md","filePath":"doc/hardware.md","lastUpdated":1792823671000}'),r={name:"doc/hardware.md"};function d(s,t,n,o,h,c){return l(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="硬件" tabindex="-1">硬件 <a class="header-anchor" href="#硬件" aria-label="Permalink to &quot;硬件&quot;">​</a></h1><h2 id="电压、电流、功率" tabindex="-1">电压、电流、功率 <a class="header-anchor" href="#电压、电流、功率" aria-label="Permalink to &quot;电压、电流、功率&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>常用单位</th></tr></thead><tbody><tr><td>电压 U</td><td>推动电荷流动的电势差</td><td>V</td></tr><tr><td>电流 I</td><td>电荷流动的速率</td><td>A / mA</td></tr><tr><td>功率 P</td><td>电能消耗或输出的速率</td><td>W</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = U × I</span></span>
<span class="line"><span># 例：5V 供电，电流 0.5A → 功率 2.5W</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>看电源参数只要会三件事：电压对不对、电流够不够、会不会短路。</p><hr><h2 id="_3-3v-与-5v-最容易烧板的地方" tabindex="-1">3.3V 与 5V：最容易烧板的地方 <a class="header-anchor" href="#_3-3v-与-5v-最容易烧板的地方" aria-label="Permalink to &quot;3.3V 与 5V：最容易烧板的地方&quot;">​</a></h2><ul><li>ESP32 的 GPIO 是 <strong>3.3V 电平</strong>，绝大多数引脚<strong>不耐 5V</strong>，直接接 5V 信号会损坏芯片。</li><li>板子上的 5V 一般只用于：USB 输入、部分外设供电（如 ws2812、继电器模块）。</li><li>模块标 <code>VCC 3.3V</code> 就接 3.3V，标 <code>5V</code> 才接 5V，不确定时先查模块手册。</li></ul><p>安全红线：</p><ol><li>不要接市电。</li><li>不要把 5V 直接接到 GPIO。</li><li>通电状态下不要随意短接引脚、不要插拔杜邦线。</li><li>接线前先断电，接完检查一遍再上电。</li></ol><hr><h2 id="gpio" tabindex="-1">GPIO <a class="header-anchor" href="#gpio" aria-label="Permalink to &quot;GPIO&quot;">​</a></h2><p>通用输入输出引脚，可读电平（按钮）也可输出电平（LED）。</p><ul><li>输出能力有限，单个引脚一般几十 mA，驱动电机、灯带要走外部电源 + 三极管/MOS。</li><li>部分引脚有复用限制：启动时电平不对会导致进不了系统、下载模式异常。</li><li>ESP32-S3 的 GPIO 编号不连续，Flash / PSRAM 占用的那几个（约 26~32）不要占用。</li><li>部分引脚只有输入能力或带内部上下拉，接之前查引脚定义表。</li></ul><hr><h2 id="三种常见通信总线" tabindex="-1">三种常见通信总线 <a class="header-anchor" href="#三种常见通信总线" aria-label="Permalink to &quot;三种常见通信总线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>总线</th><th>线数</th><th>速度</th><th>典型用途</th></tr></thead><tbody><tr><td>I²C</td><td>SDA / SCL 两根</td><td>100k~400kHz</td><td>传感器、触摸芯片、EEPROM</td></tr><tr><td>SPI</td><td>SCK / MOSI / MISO / CS</td><td>几 MHz ~ 几十 MHz</td><td>屏幕、SD 卡、高速外设</td></tr><tr><td>UART</td><td>TX / RX（+GND）</td><td>常见 115200</td><td>串口日志、模块通信</td></tr></tbody></table><p>要点：</p><ul><li><strong>I²C 需要上拉电阻</strong>，多数模块自带；同一总线设备地址不能冲突。</li><li><strong>SPI 靠 CS 选片</strong>，一主多从时每个从设备一根 CS。</li><li><strong>UART 是交叉接</strong>：A 的 TX 接 B 的 RX，并且必须共地。</li><li>三种总线都要 <strong>共地（GND）</strong>，只接信号线不接地是最常见的“没反应”原因。</li></ul><hr><h2 id="esp32-s3-资源速记" tabindex="-1">ESP32-S3 资源速记 <a class="header-anchor" href="#esp32-s3-资源速记" aria-label="Permalink to &quot;ESP32-S3 资源速记&quot;">​</a></h2><ul><li>双核 Xtensa LX7，主频一般 240MHz，带 Wi-Fi + BLE。</li><li>常见 Flash 8/16MB、PSRAM 2/8MB，跑 LVGL 建议带 PSRAM。</li><li>外设：多路 GPIO、2 路 I²C、多路 SPI、3 路 UART、ADC、PWM(LEDC)、USB。</li><li>ADC 为 12 位，精度一般，测量电池电压够用，别当万用表用。</li></ul><hr><h2 id="烧录与运行" tabindex="-1">烧录与运行 <a class="header-anchor" href="#烧录与运行" aria-label="Permalink to &quot;烧录与运行&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>电脑 --USB--&gt; 板载 USB 转串口/原生 USB --&gt; ESP32-S3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>常见两种下载方式：板载 USB 转串口芯片（CH340/CP2102 类），或 ESP32-S3 原生 USB。</li><li>进不了下载模式时：<strong>按住 BOOT 不放，点一下 RST 松开</strong>，再点上传。</li><li>上传失败先看三件事：驱动装没装、串口号选对没、有没有别的串口工具占着端口。</li><li>程序跑起来后可以用串口日志看输出，波特率一般 115200。</li></ul><hr><h2 id="屏幕与-lvgl" tabindex="-1">屏幕与 LVGL <a class="header-anchor" href="#屏幕与-lvgl" aria-label="Permalink to &quot;屏幕与 LVGL&quot;">​</a></h2><h3 id="屏幕基础参数" tabindex="-1">屏幕基础参数 <a class="header-anchor" href="#屏幕基础参数" aria-label="Permalink to &quot;屏幕基础参数&quot;">​</a></h3><ul><li><strong>分辨率</strong>：如 320×240、480×320，决定绘图坐标范围。</li><li><strong>颜色深度</strong>：常见 RGB565（16 位，2 字节/像素），一张 320×240 全屏缓冲约 150KB。</li><li><strong>驱动 IC</strong>：常见 ST7789、ILI9341 一类，具体型号以板子原理图和例程为准。</li><li><strong>触摸</strong>：电容屏常见 I²C 接口的触摸芯片（GT911、CST328 一类），坐标需要做方向/镜像校正。</li></ul><h3 id="lvgl-要点" tabindex="-1">LVGL 要点 <a class="header-anchor" href="#lvgl-要点" aria-label="Permalink to &quot;LVGL 要点&quot;">​</a></h3><ul><li>开源嵌入式 GUI 库，控件（label、bar、btn、table）都是对象，靠事件回调响应。</li><li>用 <strong>局部刷新 + 双缓冲</strong>，不要整屏重绘，否则会闪。</li><li>刷新是单线程的：网络回调里不要直接改控件，交给主循环/任务队列处理。</li><li>内存吃紧时优先降颜色深度、减少同时存在的控件和图片资源。</li></ul><hr><h2 id="网络长连接" tabindex="-1">网络长连接 <a class="header-anchor" href="#网络长连接" aria-label="Permalink to &quot;网络长连接&quot;">​</a></h2><ul><li><strong>Wi-Fi</strong>：连上不等于能用，要判断是否真正拿到 IP 并通外网。</li><li><strong>MQTT</strong>：适合设备上报/订阅，需要心跳（keepalive）和断线重连。</li><li><strong>WebSocket</strong>：适合和 Spring Boot 服务双向推送，同样要做重连和退避。</li><li>断网重连要写指数退避（1s、2s、4s…），不要死循环猛连，容易把路由器打挂。</li><li>涉及时间的地方记得做 NTP 对时，否则日志时间线全乱。</li></ul><hr><h2 id="串口调试与排障" tabindex="-1">串口调试与排障 <a class="header-anchor" href="#串口调试与排障" aria-label="Permalink to &quot;串口调试与排障&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先排查</th></tr></thead><tbody><tr><td>黑屏</td><td>背光是否供电、屏幕初始化代码、SPI 引脚定义</td></tr><tr><td>一上电就重启</td><td>供电电流不足、看门狗复位、程序崩溃后 panic 重启</td></tr><tr><td>连不上 Wi-Fi</td><td>SSID/密码、2.4G/5G 频段、天线</td></tr><tr><td>触摸没反应</td><td>I²C 地址、触摸中断脚、坐标校准</td></tr><tr><td>烧录失败</td><td>驱动、串口占用、BOOT 按键时序、供电</td></tr></tbody></table><p>万用表三件事就够用：量直流电压、测通断、查短路。</p><hr><h2 id="入门学习顺序" tabindex="-1">入门学习顺序 <a class="header-anchor" href="#入门学习顺序" aria-label="Permalink to &quot;入门学习顺序&quot;">​</a></h2><ol><li>硬件与供电安全 —— 能安全接线、不烧板。</li><li>ESP32 与烧录 —— 能跑通官方示例。</li><li>C/C++ 基础 —— 能看懂并修改示例代码。</li><li>屏幕与 LVGL —— 能做出状态卡片、进度条、多页面。</li><li>网络与长连接 —— 能接收 PC / NAS 推送并自动重连。</li><li>调试与维护 —— 出问题能定位，而不是只会重新烧录。</li></ol>`,42)])])}const u=a(r,[["render",d]]);export{b as __pageData,u as default};
